pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        bool ok = false;
        try c.addReward(address(1)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "reference succeeds, bug fails");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Call addReward to set up state (this is the entry referenced in the difference statement)
        c.addReward(address(0x1234));
        // Try to transfer ownership to a new address
        address newOwner = address(0x5678);
        // Reference C will update owner; buggy M will not
        vm.prank(c.owner()); // owner is address(this) from setUp
        c.transferOwnership(newOwner);
        // The reference holds: owner should be newOwner; bug breaks: owner remains address(this)
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Deployer is address(this), so rewardDistributor is address(this) initially
        // Call addReward with a dummy token address
        address dummyToken = address(0x1234);
        c.addReward(dummyToken);
        // After the call, reference keeps rewardDistributor = address(this)
        // Bug sets rewardDistributor = address(0)
        assertTrue(c.rewardDistributor() == address(this));
    }
}
